                        mesgDefinitionListener->OnMesgDefinition(localMesgDefs[localMesgIndex]);
                    }
                    checkPause = true;
                    break;

                case RETURN_END_OF_FILE:
                    currentByteIndex = (FIT_UINT32)(p - buffer) + 1;
                    currentByteOffset = offset + 1;
                    return FIT_TRUE;

                default:
                    currentByteIndex = (FIT_UINT32)(p - buffer);
                    currentByteOffset = offset + 1;
                    return FIT_TRUE;
            }
